import math
S={'phase':'rev','theta':0.0,'t0':0.0,'woke':False,'n':0,'free0':9.0}
def wrap(a):
    return (a+180.0)%360.0-180.0
def clamp(x,a,b):
    return max(a,min(b,x))
def control(obs):
    S['n']+=1
    rig=obs['rig']; h=obs['hitch_deg']; t=obs['t']
    rear=rig['trailer_rear']; hw=rig['trailer_half_width']
    look=rig.get('screen_gaze_deg')
    if look is None: look=-23
    beta=rig['trailer_heading_deg']+180.0
    pts=[]
    views=obs.get('views') or {}
    for name,v in views.items():
        o=v['origin']
        for w in v.get('walls',[]):
            b,d=w[0],w[1]
            px=o[0]+d*math.cos(math.radians(b)); py=o[1]+d*math.sin(math.radians(b))
            dx=px-rear[0]; dy=py-rear[1]
            r=math.hypot(dx,dy)
            rel=wrap(math.degrees(math.atan2(dy,dx))-beta)
            pts.append((r*math.cos(math.radians(rel)), r*math.sin(math.radians(rel))))
    def free(th):
        c=math.cos(math.radians(th)); s=math.sin(math.radians(th)); f=9.0
        for a,l in pts:
            al=a*c+l*s; pe=-a*s+l*c
            if al>0 and abs(pe)<hw+0.35 and al<f: f=al
        return f
    tgt=obs.get('target') or {}
    tdist=None
    if 'camera' in views:
        cands=list(range(-80,81,4))
        fs=[free(c) for c in cands]
        S['free0']=free(0)
        mx=max(fs); i=fs.index(mx)
        if mx>=8.9:
            # pick open block closest to current heading
            ok=[k for k in range(len(cands)) if fs[k]>=0.9*mx]
            i=min(ok,key=lambda k:abs(cands[k]))
        lo=i; hi=i
        while lo>0 and fs[lo-1]>=0.9*mx: lo-=1
        while hi<len(cands)-1 and fs[hi+1]>=0.9*mx: hi+=1
        th=(cands[lo]+cands[hi])/2.0 if mx<8.9 else cands[i]
        lmin=9.0; rmin=9.0
        for a,l in pts:
            if -0.5<a<3.0:
                if l>0: lmin=min(lmin,l)
                else: rmin=min(rmin,-l)
        c=0.0
        if lmin<hw+0.8: c-=(hw+0.8-lmin)*25
        if rmin<hw+0.8: c+=(hw+0.8-rmin)*25
        th+=clamp(c,-15,15)
        if tgt.get('in_sight') and tgt.get('dist_m') is not None:
            e=rig['eye']; b=math.radians(tgt['bearing_deg']); d=tgt['dist_m']
            px=e[0]+d*math.cos(b); py=e[1]+d*math.sin(b)
            dx=px-rear[0]; dy=py-rear[1]
            tdist=math.hypot(dx,dy)
            tr=wrap(math.degrees(math.atan2(dy,dx))-beta)
            if tdist<12 and abs(tr)<70 and free(tr)>=min(tdist-0.5,4.0):
                th=0.3*th+0.7*tr
        S['theta']=0.5*S['theta']+0.5*th
        S['tdist']=tdist
    th=S['theta']; tdist=S.get('tdist')
    if S['phase']=='rev':
        if abs(h)>40:
            S['phase']='fwd'; S['t0']=t
            print('pull fwd at t=%.1f h=%.1f'%(t,h))
    if S['phase']=='fwd':
        if (t-S['t0']>2.5 and abs(h)<8) or t-S['t0']>6:
            S['phase']='rev'
        else:
            return (0.0,1.5,look)
    cap=25.0
    if tdist is not None and tdist<7: cap=12.0
    hd=clamp(-1.0*th,-cap,cap)
    steer=clamp(2.0*(h-hd),-34,34)
    sp=-1.0
    if S['free0']>6 and abs(h)<10 and abs(th)<10: sp=-1.5
    if tdist is not None and tdist<6: sp=-0.7
    if S['free0']<0.3:
        sp=0.0
        if not S['woke']:
            S['woke']=True
            try: wake('blocked straight back, stopped')
            except Exception: pass
    if S['n']%20==0:
        print('t=%.1f h=%.1f th=%.1f hd=%.1f st=%.1f f0=%.1f td=%s'%(t,h,th,hd,steer,S['free0'],tdist))
    return (steer,sp,look)

