import math
fd=0.0
last=None
done=False
woke=False
lp=-10

def control(obs):
    global fd,last,done,woke,lp
    t=obs['t']; v=obs['motion']['v_mps']
    if last is not None and v>0: fd+=v*max(0.0,min(0.5,t-last))
    last=t
    rig=obs['rig']
    vf=rig.get('vehicle_front',3.2)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    try: vf=float(vf)
    except Exception: vf=3.2
    hw=rig.get('vehicle_half_width',1.15) or 1.15
    phi=obs['hitch_deg']
    ming=9.0; why=''
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for w in vw.get('walls') or []:
            b=math.radians(w[0]); d=w[1]
            x=o[0]+d*math.cos(b); y=o[1]+d*math.sin(b)
            if 0.3<x<vf+1.2:
                g=max(abs(y)-hw, x-vf)
                if g<ming: ming=g; why='%s %.2f %.2f'%(name,x,y)
    if not done and ming<0.22 and v>0.02:
        done=True
        if not woke: woke=True; wake('front rail close gap %.2f at %s, phi %.1f fd %.1f'%(ming,why,phi))
    if not done and (phi>-8 or fd>3.0):
        done=True
        if not woke: woke=True; wake('forward recovery done phi %.1f fd %.1f'%(phi,fd))
    if done:
        spd=0.0; steer=max(-45,min(45,-1.5*phi))
    else:
        spd=0.4; steer=45.0 if phi<-12 else max(-45,min(45,-2.0*phi))
    if t-lp>1.5:
        lp=t
        print('t%.1f fd %.2f phi %.1f gap %.2f %s done %s'%(t,fd,phi,ming,why,done))
    return (steer,spd,-25)

