import math
mode='rev'
last_c=0.0
lastp=-10
L=1.25;LT=0.85;B=0.3
def wrap(a):
    return (a+180)%360-180
def control(obs):
    global mode,last_c,lastp
    phi=obs['hitch_deg']; rig=obs['rig']
    th=rig['trailer_heading_deg']; R=rig['trailer_rear']
    bb=math.radians(th+180); ux,uy=math.cos(bb),math.sin(bb); px,py=uy,-ux
    look=170
    if mode=='fwd':
        if abs(phi)<8:
            mode='rev'
        else:
            return (0.0,0.5,look)
    if abs(phi)>45:
        mode='fwd'
        return (0.0,0.5,look)
    pts=[]
    views=obs.get('views') or {}
    for k in ('direct','periphery'):
        v=views.get(k)
        if not v: continue
        ox,oy=v['origin']
        for w in v.get('walls',[]):
            b,d=w[0],w[1]
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            dx,dy=x-R[0],y-R[1]
            pts.append((dx*ux+dy*uy, dx*px+dy*py))
    left=[l for a,l in pts if -0.5<a<3.0 and l>0]
    right=[l for a,l in pts if -0.5<a<3.0 and l<0]
    lmin=min(left) if left else None
    rmax=max(right) if right else None
    if lmin is not None and rmax is not None:
        c=(lmin+rmax)/2
    elif lmin is not None:
        c=min(0.0,lmin-1.0)
    elif rmax is not None:
        c=max(0.0,rmax+1.0)
    else:
        c=last_c*0.9
    last_c=c
    aim_a,aim_l=2.0,c
    tg=obs.get('target') or {}
    src='rails'
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        e=rig['eye']; tb=math.radians(tg['bearing_deg']); td=tg['dist_m']
        tx=e[0]+td*math.cos(tb)-R[0]; ty=e[1]+td*math.sin(tb)-R[1]
        ta=tx*ux+ty*uy; tl=tx*px+ty*py
        if ta>0.3:
            aim_a=max(ta,1.5); aim_l=tl; src='tgt'
            if lmin is not None: aim_l=min(aim_l,lmin-0.7)
            if rmax is not None: aim_l=max(aim_l,rmax+0.7)
    phid=math.degrees(math.atan2(aim_l,aim_a))*1.0
    phid=max(-30,min(30,phid))
    pr=math.radians(phid)
    deq=math.degrees(math.atan(L*math.sin(pr)/(LT+B*math.cos(pr))))
    steer=deq+2.0*(phi-phid)
    steer=max(-45,min(45,steer))
    if obs['t']-lastp>=2.0:
        lastp=obs['t']
        print('t%.1f phi%.1f phid%.1f st%.1f c%.2f l%s r%s %s prog%s'%(obs['t'],phi,phid,steer,c,lmin,rmax,src,obs.get('progress',{}).get('covered')))
    return (steer,-0.35,look)

