import math
phase='rev'
last_alpha=0.0
fwd_t=0.0
cnt=0

def pts_of(obs):
    P=[]
    for k,v in (obs.get('views') or {}).items():
        if not v: continue
        o=v.get('origin',[0,0])
        for b,d in v.get('walls',[]) or []:
            r=math.radians(b)
            P.append((o[0]+d*math.cos(r),o[1]+d*math.sin(r)))
    return P

def clearance(P,rear,u,n,a,hw=1.7,cap=15.0):
    w=(math.cos(a)*u[0]+math.sin(a)*n[0], math.cos(a)*u[1]+math.sin(a)*n[1])
    c=cap
    for p in P:
        dx=p[0]-rear[0]; dy=p[1]-rear[1]
        s=dx*w[0]+dy*w[1]
        if s<=0.3: continue
        q=abs(-dx*w[1]+dy*w[0])
        if q<hw and s<c: c=s
    return c

def control(obs):
    global phase,last_alpha,fwd_t,cnt
    cnt+=1
    h=obs['hitch_deg']; rig=obs['rig']
