    for k,v in (obs.get('views') or {}).items():
        if not v: continue
        if only and k not in only: continue
        o=v.get('origin',[0,0])
        for b,d in v.get('walls',[]) or []:
            r=math.radians(b)
            P.append((o[0]+d*math.cos(r),o[1]+d*math.sin(r)))
    return P

def fit_right(obs):
    Q=[p for p in pts_of(obs,('direct','periphery')) if 2.0<p[0]<12.0 and -5.0<p[1]<-0.3]
    if len(Q)<3: return None
    n=len(Q); mx=sum(p[0] for p in Q)/n; my=sum(p[1] for p in Q)/n
    sxx=sum((p[0]-mx)**2 for p in Q)
    if sxx<1.0: return None
    b=sum((p[0]-mx)*(p[1]-my) for p in Q)/sxx
    a=my-b*mx
    return (a,b)

def clearance(P,rear,u,n,a,hw=1.7,cap=15.0):
    w=(math.cos(a)*u[0]+math.sin(a)*n[0], math.cos(a)*u[1]+math.sin(a)*n[1])
    c=cap
    for p in P:
        dx=p[0]-rear[0]; dy=p[1]-rear[1]
        s=dx*w[0]+dy*w[1]
        if s<=0.3: continue
        q=abs(-dx*w[1]+dy*w[0])
        if q<hw and s<c: c=s
    return c

def control(obs):
    global phase,last_alpha,fwd_t,fwd_d,cnt,linemem
    cnt+=1
    h=obs['hitch_deg']; rig=obs['rig']
    rear=rig['trailer_rear']; hit=rig['hitch']
    ux=rear[0]-hit[0]; uy=rear[1]-hit[1]; L=math.hypot(ux,uy) or 1.0
    u=(ux/L,uy/L); n=(u[1],-u[0])
    if n[1]<0: n=(-n[0],-n[1])
    dt=obs.get('dt',0.1)
    look=-41
    st=obs.get('status')
    v=obs['motion']['v_mps']
    ln=fit_right(obs)
    if ln: linemem=ln
    if phase=='fwd0':
        if v>0: fwd_d+=v*dt
        if fwd_d>7.0:
            phase='rev'
        else:
            if linemem:
                a,b=linemem
                psi=math.degrees(math.atan(b))
                c=-(a+b*1.0)-1.275
                s=1.5*(psi+15*(1.4-c))
            else:
                psi=0;c=-1;s=10
            s=max(-25,min(25,s))
            if cnt%10==0: print('F t=%.1f d=%.1f psi=%.1f c=%.2f s=%.1f h=%.1f'%(obs['t'],fwd_d,psi,c,s,h))
            return (s,1.2,look)
    if phase=='rev' and (abs(h)>52 or st=='JACKKNIFED'):
        phase='fwd'; fwd_t=0.0
    if phase=='fwd':
        fwd_t+=dt
        if abs(h)<8 or fwd_t>6.0:
            phase='rev'
        else:
            return (max(-42,min(42,-0.8*h)),1.0,look)
    P=pts_of(obs)
    alpha=last_alpha
    if P:
        best=None
        for i in range(-13,14):
            a=math.radians(i*5)
            c=clearance(P,rear,u,n,a)
            sc=c-0.02*abs(i*5)-0.01*abs(i*5-math.degrees(last_alpha))
            if best is None or sc>best[0]: best=(sc,a,c)
        alpha=best[1]
        lefts=[];rights=[]
        for p in P:
            dx=p[0]-rear[0]; dy=p[1]-rear[1]
            al=dx*u[0]+dy*u[1]; la=dx*n[0]+dy*n[1]
            if -4<al<5:
                if la>0: lefts.append(la)
                else: rights.append(la)
        if lefts and rights and abs(alpha)<math.radians(12):
            c=(min(lefts)+max(rights))/2.0
            alpha+=0.8*math.atan2(c,6.0)
    tg=obs.get('target') or {}
    dist_t=None
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tx=e[0]+d*math.cos(b); ty=e[1]+d*math.sin(b)
        dx=tx-rear[0]; dy=ty-rear[1]
        al=dx*u[0]+dy*u[1]; la=dx*n[0]+dy*n[1]
        dist_t=math.hypot(dx,dy)
        if al>0.5:
            at=math.atan2(la,al)
            if not P or clearance(P,rear,u,n,at,1.4)>=min(dist_t,15.0)-1.0:
                alpha=at
    last_alpha=alpha
    hdes=max(-35,min(35,1.2*math.degrees(alpha)))
    fx=hit[0]-u[0]*1.4; fy=hit[1]-u[1]*1.4
    crx=fx-n[0]*1.275; cry=fy-n[1]*1.275
    cc=9.0
    if ln:
        a,b=ln
        cc=(cry-(a+b*crx))*math.cos(math.atan(b))-0.3
    sp=-1.0
    if cc<0.5 and h>0:
        hdes=min(hdes,h-10*(0.5-cc)/0.5-2)
        sp=-0.6
    steer=0.38*h+1.5*(h-hdes)
    steer=max(-42,min(42,steer))
    if dist_t is not None and dist_t<12: sp=-0.6
    if cnt%20==0:
        print('t=%.1f h=%.1f a=%.1f hd=%.1f st=%.1f cc=%.2f dt=%s'%(obs['t'],h,math.degrees(alpha),hdes,steer,cc,dist_t))
    return (steer,sp,look)

